grid = [[0]*30 for _ in range(30)]
for r, line in enumerate(lines):
    row_vals = [int(x) for x in line.split()]
    if len(row_vals) > 30:
        row_vals = row_vals[:30]
    grid[r][:len(row_vals)] = row_vals

visited = [[False]*30 for _ in range(30)]
regions = []

for r in range(30):
    for c in range(30):
        if grid[r][c] == 1 and not visited[r][c]:
            region = []
            q = deque([(r,c)])
            visited[r][c] = True
            while q:
                cr, cc = q.popleft()
                region.append((cr, cc))
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < 30 and 0 <= nc < 30 and grid[nr][nc] == 1 and not visited[nr][nc]:
                        visited[nr][nc] = True
                        q.append((nr, nc))
            regions.append(region)

# Sort by size
regions_by_size = sorted(regions, key=lambda r: len(r), reverse=True)
for i, region in enumerate(regions_by_size):
    print(f"  Region size {i+1}: {len(region)} cells, bbox area: {((max([r for r,c in region])-min([r for r,c in region]))+1)*((max([c for r,c in region])-min([c for r,c in region]))+1)}")

# Try: only transform small regions (size < 20)
output = [row[:] for row in grid]

total_2s = 0
total_3s = 0

for i, region in enumerate(regions):
    if len(region) > 15:  # Only small frames
        continue

    rs = [r for r, c in region]
    cs = [c for r, c in region]
    rmin, rmax = min(rs), max(rs)
    cmin, cmax = min(cs), max(cs)

    boundary_ones = 0
    interior_zeros = 0
    for r in range(rmin, rmax + 1):
        for c in range(cmin, cmax + 1):
            if grid[r][c] == 1:
                if r == rmin or r == rmax or c == cmin or c == cmax:
                    boundary_ones += 1
            elif rmin < r < rmax and cmin < c < cmax:
                interior_zeros += 1

    print(f"Transform Region: bbox={rmin}-{rmax}x{cmin}-{cmax}, uses {boundary_ones} border + {interior_zeros} interior = {boundary_ones + interior_zeros} cells")
    total_to_transform = boundary_ones + interior_zeros
    total_2s += boundary_ones
    total_3s += interior_zeros

    for r in range(rmin, rmax + 1):
        for c in range(cmin, cmax + 1):
            if (r, c) not in region:
                if r == rmin or r == rmax or c == cmin or c == cmax:
                    output[r][c] = 2
                else:
                    output[r][c] = 3

print(f"\nTransformed cells: {total_2s} 2s and {total_3s} 3s (total={total_2s+total_3s})")
print(f"Final: 0s={sum(r.count(0) for r in output)}, 1s={sum(r.count(1) for r in output)}, 2s={sum(r.count(2) for r in output)}, 3s={sum(r.count(3) for r in output)}")
print(json.dumps({"action": "submit", "grid": output}))

